import { bindHostedTaskInputAuthority, inheritHostedTaskInputAuthority } from "./task-input.js";
import { hostedInheritedInferenceModelResolver, hostedInheritedRootRunId, hostedInheritedTaskInput, } from "./terminal-credential.js";
import { bindHostedPlatformDependencyRuntime } from "./platform-dependency-credential.js";
import { inheritHostedChildInferenceAuthority } from "./inference-credential.js";
import { startAgentRuntimeForkWithHostTools, } from "../streaming/fork-runtime-stream.js";
import { monitorHostedChildRunStatus, } from "./child-status.js";
import { composeAbortSignals } from "./child-stream-watchdog.js";
/** Starts hosted child fork runtime with host tools. */
export function startHostedChildForkRuntimeWithHostTools(input) {
    const { durableChildRun, childRunMonitorPollIntervalMs, monitorChildRunStatus, abortSignal, ...runtimeInput } = input;
    inheritHostedChildInferenceAuthority(runtimeInput, input);
    const taskInput = durableChildRun
        ? hostedInheritedTaskInput(durableChildRun, runtimeInput.projectId ?? "")
        : undefined;
    bindHostedTaskInputAuthority(runtimeInput, taskInput, {
        projectId: runtimeInput.projectId,
        runId: durableChildRun?.childRunId,
        rootRunId: taskInput && durableChildRun
            ? hostedInheritedRootRunId(durableChildRun, runtimeInput.projectId ?? "") ??
                taskInput.rootRunId
            : undefined,
    });
    const forkStreamAbortController = new AbortController();
    const forkStreamAbortSignal = composeAbortSignals([
        abortSignal,
        forkStreamAbortController.signal,
    ]);
    const childRunMonitorAbortController = durableChildRun ? new AbortController() : null;
    const childRunMonitorSignal = childRunMonitorAbortController
        ? composeAbortSignals([abortSignal, childRunMonitorAbortController.signal])
        : undefined;
    const monitor = monitorChildRunStatus ?? monitorHostedChildRunStatus;
    const abortForkStream = (error) => {
        if (!forkStreamAbortController.signal.aborted) {
            forkStreamAbortController.abort(error);
        }
    };
    const childRunMonitorPromise = durableChildRun
        ? monitor({
            authToken: runtimeInput.authToken,
            apiUrl: runtimeInput.apiUrl,
            identifiers: durableChildRun,
            abortSignal: childRunMonitorSignal,
            pollIntervalMs: childRunMonitorPollIntervalMs ?? 2_000,
            onTerminal: abortForkStream,
            onMonitoringExhausted: abortForkStream,
        })
        : Promise.resolve();
    const forkInput = {
        ...runtimeInput,
        ...(durableChildRun
            ? { createModelRuntimeResolver: () => hostedInheritedInferenceModelResolver(durableChildRun) }
            : {}),
        abortSignal: forkStreamAbortSignal,
    };
    inheritHostedChildInferenceAuthority(forkInput, runtimeInput);
    inheritHostedTaskInputAuthority(forkInput, runtimeInput);
    if (durableChildRun)
        bindHostedPlatformDependencyRuntime(forkInput, durableChildRun);
    const { streamResult, forkToolNames } = startAgentRuntimeForkWithHostTools(forkInput);
    return {
        forkStreamAbortController,
        childRunMonitorAbortController,
        childRunMonitorPromise,
        streamResult,
        forkToolNames,
    };
}
